"use client";

import { ChevronsUpDownIcon } from "lucide-react";
import { useCallback, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Command,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/ui/command";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { useBrandSearch } from "@/registry/new-york/hooks/use-brand-search";
import {
  type BrandSearchResult,
  withLogoParams,
} from "@/registry/new-york/lib/logo-dev";

interface BrandSearchProps {
  className?: string;
  defaultValue?: BrandSearchResult | null;
  disabled?: boolean;
  /** Server endpoint proxying the Logo.dev Search API. */
  endpoint?: string;
  /** Maximum results shown. Default 8. */
  limit?: number;
  onSelect?: (brand: BrandSearchResult) => void;
  placeholder?: string;
  /** Controlled selection. Leave undefined for uncontrolled use. */
  value?: BrandSearchResult | null;
}

const RESULT_LOGO_PX = 20;

const resultLogoUrl = (brand: BrandSearchResult) =>
  // logo_url already carries a token; just request a crisp, small render.
  withLogoParams(brand.logo_url, {
    format: "webp",
    size: RESULT_LOGO_PX * 2,
  });

const BrandSearchResultItem = ({
  brand,
  onSelect,
}: {
  brand: BrandSearchResult;
  onSelect: (brand: BrandSearchResult) => void;
}) => {
  const handleSelect = useCallback(() => {
    onSelect(brand);
  }, [brand, onSelect]);
  return (
    <CommandItem onSelect={handleSelect} value={brand.domain}>
      <img
        alt=""
        className="rounded-sm"
        height={RESULT_LOGO_PX}
        loading="lazy"
        src={resultLogoUrl(brand)}
        width={RESULT_LOGO_PX}
      />
      <span className="truncate">{brand.name}</span>
      <span className="ml-auto text-muted-foreground text-xs">
        {brand.domain}
      </span>
    </CommandItem>
  );
};

/**
 * Company autocomplete backed by the Logo.dev Search API — pick a company by
 * name and get its domain and logo. Requires the API route installed with
 * this block (your sk_ key stays on the server).
 */
function BrandSearch({
  value,
  defaultValue,
  onSelect,
  endpoint,
  placeholder = "Search for a company…",
  limit,
  disabled,
  className,
}: BrandSearchProps) {
  const [open, setOpen] = useState(false);
  const [internal, setInternal] = useState<BrandSearchResult | null>(
    defaultValue ?? null
  );
  const selected = value === undefined ? internal : value;

  const { query, setQuery, results, isLoading, error } = useBrandSearch({
    enabled: open,
    endpoint,
    limit,
  });

  const handleSelect = useCallback(
    (brand: BrandSearchResult) => {
      if (value === undefined) {
        setInternal(brand);
      }
      onSelect?.(brand);
      setOpen(false);
    },
    [value, onSelect]
  );

  const showStatus = results.length === 0;
  let status: string | null = null;
  if (showStatus && isLoading) {
    status = "Searching…";
  } else if (showStatus && error) {
    status = "Something went wrong. Try again.";
  } else if (showStatus && query.trim()) {
    status = "No companies found.";
  }

  return (
    <Popover onOpenChange={setOpen} open={open}>
      <PopoverTrigger asChild>
        <Button
          aria-expanded={open}
          className={cn("w-full justify-between font-normal", className)}
          disabled={disabled}
          role="combobox"
          variant="outline"
        >
          {selected ? (
            <span className="flex min-w-0 items-center gap-2">
              <img
                alt=""
                className="rounded-sm"
                height={RESULT_LOGO_PX}
                src={resultLogoUrl(selected)}
                width={RESULT_LOGO_PX}
              />
              <span className="truncate">{selected.name}</span>
            </span>
          ) : (
            <span className="text-muted-foreground">{placeholder}</span>
          )}
          <ChevronsUpDownIcon className="size-4 shrink-0 opacity-50" />
        </Button>
      </PopoverTrigger>
      <PopoverContent
        align="start"
        className="w-(--radix-popover-trigger-width) p-0"
      >
        {/* The API filters server-side; local cmdk filtering must stay off. */}
        <Command shouldFilter={false}>
          <CommandInput
            onValueChange={setQuery}
            placeholder={placeholder}
            value={query}
          />
          <CommandList>
            {status ? (
              <p className="py-6 text-center text-muted-foreground text-sm">
                {status}
              </p>
            ) : (
              <CommandGroup>
                {results.map((brand) => (
                  <BrandSearchResultItem
                    brand={brand}
                    key={brand.domain}
                    onSelect={handleSelect}
                  />
                ))}
              </CommandGroup>
            )}
          </CommandList>
        </Command>
      </PopoverContent>
    </Popover>
  );
}

export type { BrandSearchProps };
export { BrandSearch };

"use client";

import { useEffect, useRef, useState } from "react";
import type { BrandSearchResult } from "@/registry/new-york/lib/logo-dev";

interface UseBrandSearchOptions {
  debounceMs?: number;
  enabled?: boolean;
  /**
   * Server endpoint that proxies the Logo.dev Search API with your secret
   * key. Defaults to the Next.js route installed with the brand-search
   * block; point it at your own proxy on other stacks.
   */
  endpoint?: string;
  /** Maximum results to keep (the API returns up to 10). Default 8. */
  limit?: number;
}

const DEFAULT_DEBOUNCE_MS = 200;
const DEFAULT_LIMIT = 8;

const performSearch = async (
  endpoint: string,
  query: string,
  limit: number,
  signal: AbortSignal
): Promise<BrandSearchResult[]> => {
  const response = await fetch(`${endpoint}?q=${encodeURIComponent(query)}`, {
    signal,
  });
  if (!response.ok) {
    throw new Error(`Brand search failed (${response.status})`);
  }
  const data = (await response.json()) as BrandSearchResult[];
  return data.slice(0, limit);
};

const isAbortError = (caught: unknown): boolean =>
  caught instanceof DOMException && caught.name === "AbortError";

/**
 * Debounced company search against the Logo.dev Search API. Stale in-flight
 * requests are aborted, and previous results stay visible while a new query
 * loads so the list doesn't flicker.
 */
function useBrandSearch({
  endpoint = "/api/logo-dev/search",
  debounceMs = DEFAULT_DEBOUNCE_MS,
  limit = DEFAULT_LIMIT,
  enabled = true,
}: UseBrandSearchOptions = {}) {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<BrandSearchResult[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const abortRef = useRef<AbortController | null>(null);

  useEffect(() => {
    const trimmed = query.trim();
    if (!(enabled && trimmed)) {
      abortRef.current?.abort();
      setResults([]);
      setIsLoading(false);
      setError(null);
      return;
    }

    const timer = setTimeout(() => {
      abortRef.current?.abort();
      const controller = new AbortController();
      abortRef.current = controller;
      setIsLoading(true);

      performSearch(endpoint, trimmed, limit, controller.signal)
        .then((data) => {
          setResults(data);
          setError(null);
        })
        .catch((caught: unknown) => {
          if (!isAbortError(caught)) {
            setError(
              caught instanceof Error
                ? caught
                : new Error("Brand search failed")
            );
          }
        })
        .finally(() => {
          // A newer request may already own the loading state.
          if (abortRef.current === controller) {
            setIsLoading(false);
          }
        });
    }, debounceMs);

    return () => clearTimeout(timer);
  }, [query, enabled, endpoint, debounceMs, limit]);

  useEffect(() => () => abortRef.current?.abort(), []);

  return { error, isLoading, query, results, setQuery };
}

export type { UseBrandSearchOptions };
export { useBrandSearch };

/**
 * Proxy for the Logo.dev Search API. Keeps your secret (sk_) key on the
 * server — never call api.logo.dev directly from the browser.
 *
 * NOTE: This route is unauthenticated. Add your own rate limiting and/or
 * auth before shipping it on a public site.
 */

const SEARCH_API_URL = "https://api.logo.dev/search";
const MAX_QUERY_LENGTH = 100;
const HTTP_BAD_REQUEST = 400;
const HTTP_NOT_FOUND = 404;
const HTTP_SERVER_ERROR = 500;
const HTTP_BAD_GATEWAY = 502;

export async function GET(request: Request): Promise<Response> {
  const query = new URL(request.url).searchParams.get("q")?.trim() ?? "";
  if (!query) {
    return Response.json([]);
  }
  if (query.length > MAX_QUERY_LENGTH) {
    return Response.json(
      { error: "Query too long" },
      { status: HTTP_BAD_REQUEST }
    );
  }

  const key = process.env.LOGO_DEV_SECRET_KEY;
  if (!key || key.startsWith("pk_")) {
    return Response.json(
      {
        error:
          "Set LOGO_DEV_SECRET_KEY to a secret (sk_) key. Get one at https://www.logo.dev/dashboard",
      },
      { status: HTTP_SERVER_ERROR }
    );
  }

  let upstream: Response;
  try {
    upstream = await fetch(`${SEARCH_API_URL}?q=${encodeURIComponent(query)}`, {
      headers: { Authorization: `Bearer ${key}` },
    });
  } catch {
    return Response.json([], { status: HTTP_BAD_GATEWAY });
  }

  // The Search API returns 404 when nothing matches — that's an empty
  // result, not an error.
  if (upstream.status === HTTP_NOT_FOUND) {
    return Response.json([]);
  }
  if (!upstream.ok) {
    return Response.json([], { status: HTTP_BAD_GATEWAY });
  }

  const results: unknown = await upstream.json();
  return Response.json(results, {
    headers: {
      "Cache-Control": "private, max-age=60, stale-while-revalidate=300",
    },
  });
}
